import{c as e,Q as d,j as o,m as a}from"./chunks/framework.BfXm-OOo.js";const u=JSON.parse('{"title":"Built-in Tools","description":"","frontmatter":{},"headers":[],"relativePath":"builtin-tools.md","filePath":"builtin-tools.md"}'),r={name:"builtin-tools.md"};function s(i,t,l,c,h,n){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="built-in-tools" tabindex="-1">Built-in Tools <a class="header-anchor" href="#built-in-tools" aria-label="Permalink to &quot;Built-in Tools&quot;">​</a></h1><p>The harness ships 18 built-in tools. ACL for each is set in <code>tools.builtin</code> of the profile YAML (or inherited from <code>mode:</code>).</p><h2 id="acl-values" tabindex="-1">ACL values <a class="header-anchor" href="#acl-values" aria-label="Permalink to &quot;ACL values&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><code>allow</code></td><td>Tool executes without prompting</td></tr><tr><td><code>prompt</code></td><td>User must approve each call at runtime</td></tr><tr><td><code>deny</code></td><td>Tool call rejected immediately</td></tr></tbody></table><hr><h2 id="file-tools" tabindex="-1">File tools <a class="header-anchor" href="#file-tools" aria-label="Permalink to &quot;File tools&quot;">​</a></h2><h3 id="read" tabindex="-1"><code>Read</code> <a class="header-anchor" href="#read" aria-label="Permalink to &quot;`Read`&quot;">​</a></h3><p>Read a file. Returns content with line numbers (<code>cat -n</code> format).</p><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>file_path</code></td><td>string</td><td>yes</td><td>Absolute path to file</td></tr><tr><td><code>offset</code></td><td>number</td><td>no</td><td>Start line, 1-indexed (default 1)</td></tr><tr><td><code>limit</code></td><td>number</td><td>no</td><td>Max lines to read (default 2000)</td></tr></tbody></table><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;file_path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/etc/hosts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;offset&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><hr><h3 id="write" tabindex="-1"><code>Write</code> <a class="header-anchor" href="#write" aria-label="Permalink to &quot;`Write`&quot;">​</a></h3><p>Write content to a file, creating parent directories as needed.</p><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>file_path</code></td><td>string</td><td>yes</td><td>Absolute path to file</td></tr><tr><td><code>content</code></td><td>string</td><td>yes</td><td>Content to write</td></tr></tbody></table><hr><h3 id="edit" tabindex="-1"><code>Edit</code> <a class="header-anchor" href="#edit" aria-label="Permalink to &quot;`Edit`&quot;">​</a></h3><p>Replace an exact string in a file.</p><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>file_path</code></td><td>string</td><td>yes</td><td>Absolute path to file</td></tr><tr><td><code>old_string</code></td><td>string</td><td>yes</td><td>Exact text to find (must be unique unless <code>replace_all</code>)</td></tr><tr><td><code>new_string</code></td><td>string</td><td>yes</td><td>Replacement text</td></tr><tr><td><code>replace_all</code></td><td>boolean</td><td>no</td><td>Replace every occurrence (default false)</td></tr></tbody></table><hr><h3 id="grep" tabindex="-1"><code>Grep</code> <a class="header-anchor" href="#grep" aria-label="Permalink to &quot;`Grep`&quot;">​</a></h3><p>Search for a regex pattern in files.</p><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>pattern</code></td><td>string</td><td>yes</td><td>Search pattern</td></tr><tr><td><code>path</code></td><td>string</td><td>yes</td><td>File or directory to search</td></tr><tr><td><code>flags</code></td><td>string</td><td>no</td><td>grep flags (default: <code>-rn</code>)</td></tr></tbody></table><hr><h3 id="glob" tabindex="-1"><code>Glob</code> <a class="header-anchor" href="#glob" aria-label="Permalink to &quot;`Glob`&quot;">​</a></h3><p>Find files matching a glob pattern.</p><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>pattern</code></td><td>string</td><td>yes</td><td>Glob pattern (e.g. <code>src/**/*.ts</code>)</td></tr><tr><td><code>cwd</code></td><td>string</td><td>no</td><td>Working directory (default: <code>process.cwd()</code>)</td></tr></tbody></table><hr><h2 id="shell-tool" tabindex="-1">Shell tool <a class="header-anchor" href="#shell-tool" aria-label="Permalink to &quot;Shell tool&quot;">​</a></h2><h3 id="bash" tabindex="-1"><code>Bash</code> <a class="header-anchor" href="#bash" aria-label="Permalink to &quot;`Bash`&quot;">​</a></h3><p>Execute a bash command. stdout + stderr combined.</p><p><strong>ACL default:</strong> <code>prompt</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>command</code></td><td>string</td><td>yes</td><td>Shell command</td></tr><tr><td><code>timeout</code></td><td>number</td><td>no</td><td>Timeout in ms (max 120000, default 120000)</td></tr></tbody></table><hr><h2 id="skill-tool" tabindex="-1">Skill tool <a class="header-anchor" href="#skill-tool" aria-label="Permalink to &quot;Skill tool&quot;">​</a></h2><h3 id="skill" tabindex="-1"><code>Skill</code> <a class="header-anchor" href="#skill" aria-label="Permalink to &quot;`Skill`&quot;">​</a></h3><p>Load and return a skill by name. Returns the full <code>SKILL.md</code> content.</p><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Skill name as listed in the skill index</td></tr></tbody></table><hr><h3 id="contextrestore" tabindex="-1"><code>ContextRestore</code> <a class="header-anchor" href="#contextrestore" aria-label="Permalink to &quot;`ContextRestore`&quot;">​</a></h3><p>Restore the full result of an earlier tool call that was elided from the model&#39;s context projection. The result remains in the session ledger; this tool retrieves it by the stored <code>tool_call_id</code>.</p><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>Earlier tool-call id</td></tr><tr><td><code>offset</code></td><td>number</td><td>no</td><td>Character offset, default <code>0</code></td></tr><tr><td><code>limit</code></td><td>number</td><td>no</td><td>Maximum characters to restore</td></tr></tbody></table><p>When <code>limit</code> truncates output, the result ends with a remaining-character marker. Old sessions without stored tool-call ids return a clear unavailable message.</p><hr><h2 id="memory-tools" tabindex="-1">Memory tools <a class="header-anchor" href="#memory-tools" aria-label="Permalink to &quot;Memory tools&quot;">​</a></h2><p>All memory tools operate on one of three scopes:</p><table tabindex="0"><thead><tr><th>Scope</th><th>Storage</th><th>Lifetime</th></tr></thead><tbody><tr><td><code>session</code></td><td>In-memory on <code>Session</code></td><td>Until session ends</td></tr><tr><td><code>profile</code></td><td><code>&lt;artifact_dir&gt;/memory/*.md</code></td><td>Persistent, shared across all users</td></tr><tr><td><code>user</code></td><td><code>~/.harness/memory/&lt;profile&gt;/&lt;user&gt;/*.md</code></td><td>Persistent, private to one user</td></tr></tbody></table><h3 id="memoryread" tabindex="-1"><code>MemoryRead</code> <a class="header-anchor" href="#memoryread" aria-label="Permalink to &quot;`MemoryRead`&quot;">​</a></h3><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th></tr></thead><tbody><tr><td><code>scope</code></td><td><code>session</code> | <code>profile</code> | <code>user</code></td><td>yes</td></tr><tr><td><code>key</code></td><td>string</td><td>yes</td></tr></tbody></table><h3 id="memorywrite" tabindex="-1"><code>MemoryWrite</code> <a class="header-anchor" href="#memorywrite" aria-label="Permalink to &quot;`MemoryWrite`&quot;">​</a></h3><p>Default scope is <code>user</code> (private). Use <code>profile</code> to share across all users.</p><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>scope</code></td><td><code>session</code> | <code>profile</code> | <code>user</code></td><td>no</td><td>Default: <code>user</code></td></tr><tr><td><code>key</code></td><td>string</td><td>yes</td><td>Short slug (e.g. <code>project-context</code>)</td></tr><tr><td><code>content</code></td><td>string</td><td>yes</td><td>Markdown content</td></tr><tr><td><code>links</code></td><td>array</td><td>no</td><td>Graph links: <code>[{ target: &quot;other-key&quot;, relation: &quot;depends_on&quot; }]</code></td></tr></tbody></table><h3 id="memorylist" tabindex="-1"><code>MemoryList</code> <a class="header-anchor" href="#memorylist" aria-label="Permalink to &quot;`MemoryList`&quot;">​</a></h3><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th></tr></thead><tbody><tr><td><code>scope</code></td><td><code>session</code> | <code>profile</code> | <code>user</code></td><td>yes</td></tr></tbody></table><h3 id="memorydelete" tabindex="-1"><code>MemoryDelete</code> <a class="header-anchor" href="#memorydelete" aria-label="Permalink to &quot;`MemoryDelete`&quot;">​</a></h3><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th></tr></thead><tbody><tr><td><code>scope</code></td><td><code>session</code> | <code>profile</code> | <code>user</code></td><td>yes</td></tr><tr><td><code>key</code></td><td>string</td><td>yes</td></tr></tbody></table><h3 id="memorylinked" tabindex="-1"><code>MemoryLinked</code> <a class="header-anchor" href="#memorylinked" aria-label="Permalink to &quot;`MemoryLinked`&quot;">​</a></h3><p>Graph traversal — finds entries that the key links to (forward) and entries that link to the key (reverse).</p><p><strong>ACL default:</strong> <code>prompt</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>scope</code></td><td><code>session</code> | <code>profile</code> | <code>user</code></td><td>yes</td><td></td></tr><tr><td><code>key</code></td><td>string</td><td>yes</td><td>Anchor memory key</td></tr><tr><td><code>relation</code></td><td>string</td><td>no</td><td>Filter by relation type</td></tr></tbody></table><hr><h2 id="stats-tool" tabindex="-1">Stats tool <a class="header-anchor" href="#stats-tool" aria-label="Permalink to &quot;Stats tool&quot;">​</a></h2><h3 id="stats" tabindex="-1"><code>Stats</code> <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;`Stats`&quot;">​</a></h3><p>Show usage stats from telemetry: top tools, skills, MCP calls, cost breakdown.</p><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>since_days</code></td><td>number</td><td>no</td><td>Show last N days (default 7)</td></tr><tr><td><code>profile</code></td><td>string</td><td>no</td><td>Filter by profile (default: current)</td></tr></tbody></table><hr><h2 id="agent-tools" tabindex="-1">Agent tools <a class="header-anchor" href="#agent-tools" aria-label="Permalink to &quot;Agent tools&quot;">​</a></h2><h3 id="delegate" tabindex="-1"><code>Delegate</code> <a class="header-anchor" href="#delegate" aria-label="Permalink to &quot;`Delegate`&quot;">​</a></h3><p>Delegate a task to a sub-agent running under a different profile. Returns the final reply and tool summary.</p><p><strong>ACL default:</strong> <code>prompt</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>profile</code></td><td>string</td><td>yes</td><td>Target profile name (e.g. <code>researcher</code>)</td></tr><tr><td><code>task</code></td><td>string</td><td>yes</td><td>Task description for the sub-agent</td></tr></tbody></table><hr><h2 id="user-interaction-tools" tabindex="-1">User interaction tools <a class="header-anchor" href="#user-interaction-tools" aria-label="Permalink to &quot;User interaction tools&quot;">​</a></h2><h3 id="askuser" tabindex="-1"><code>AskUser</code> <a class="header-anchor" href="#askuser" aria-label="Permalink to &quot;`AskUser`&quot;">​</a></h3><p>Pause the agent loop and ask the user a question. Resumes when the user responds.</p><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>prompt</code></td><td>string</td><td>yes</td><td>Question to ask</td></tr><tr><td><code>kind</code></td><td><code>text</code> | <code>select</code> | <code>multi_select</code></td><td>yes</td><td>Input type</td></tr><tr><td><code>options</code></td><td>string[]</td><td>no</td><td>Required for <code>select</code> and <code>multi_select</code></td></tr></tbody></table><h3 id="todowrite" tabindex="-1"><code>TodoWrite</code> <a class="header-anchor" href="#todowrite" aria-label="Permalink to &quot;`TodoWrite`&quot;">​</a></h3><p>Replace the current session todo list. Always pass the complete list — this overwrites everything.</p><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th></tr></thead><tbody><tr><td><code>items</code></td><td><code>{ id, content, status, priority }[]</code></td><td>yes</td></tr></tbody></table><p><code>status</code>: <code>pending</code> | <code>in_progress</code> | <code>completed</code><br><code>priority</code>: <code>high</code> | <code>medium</code> | <code>low</code></p><h3 id="todoread" tabindex="-1"><code>TodoRead</code> <a class="header-anchor" href="#todoread" aria-label="Permalink to &quot;`TodoRead`&quot;">​</a></h3><p>Return the current todo list as JSON.</p><p><strong>ACL default:</strong> <code>allow</code></p><p>No parameters.</p><hr><h2 id="code-execution-tool" tabindex="-1">Code execution tool <a class="header-anchor" href="#code-execution-tool" aria-label="Permalink to &quot;Code execution tool&quot;">​</a></h2><h3 id="executecode" tabindex="-1"><code>ExecuteCode</code> <a class="header-anchor" href="#executecode" aria-label="Permalink to &quot;`ExecuteCode`&quot;">​</a></h3><p>Execute code in a sandbox. Requires an <code>executor:</code> block in the profile.</p><p><strong>ACL default:</strong> <code>allow</code></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>code</code></td><td>string</td><td>yes</td><td>Source code</td></tr><tr><td><code>language</code></td><td>string</td><td>yes</td><td><code>python</code>, <code>javascript</code>, <code>bash</code>, <code>ruby</code>, etc.</td></tr><tr><td><code>data</code></td><td>object</td><td>no</td><td>Passed to executor as <code>/work/data.json</code></td></tr><tr><td><code>timeout_ms</code></td><td>number</td><td>no</td><td>Override profile <code>executor.timeout_ms</code></td></tr></tbody></table><p>Returns: exit code, stdout, stderr, duration, and any files written to <code>/out/</code>.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Required in profile to enable ExecuteCode:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">executor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">docker</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  docker_image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">python:3.12-slim</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  timeout_ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30000</span></span></code></pre></div>',105)])])}const b=e(r,[["render",s]]);export{u as __pageData,b as default};
